Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='repoisnotbox', at=datetime(2026, 9, 1, 12, 0, 0), actor='assistant', title='The repository is not the box: check what is running before any claim about it', body='The repo is not the box (`~/.config/systemd/user/` outranks nix\'s units). "It is configured" needs "here is what is running": `systemctl --user show -p FragmentPath <unit>` before any claim about cadence.', rationale='Log lesson, 2026-09-01. A stale unit in ~/.config/systemd/user shadowed the nix-declared sync timer, so the configured cadence was not the running one.', supersedes=()))